-- Staff base (decision 39: OS is the source; ERP payroll/HR in erp.staff_payroll / erp.staff_hr_profiles). branch_id = home branch. One login = one staff row = one org (decision 37).
create table core.staff (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  branch_id uuid,
  user_id uuid unique,
  employee_code text,
  first_name text not null,
  last_name text,
  full_name text generated always as (btrim(first_name || coalesce(' ' || last_name, ''))) stored,
  email text,
  phone text,
  gender text check (gender is null or gender in ('female','male','other')),
  dob date,
  photo_file_id uuid,
  position_id uuid,
  department_id uuid,
  wing_id uuid,
  reports_to uuid,
  language text not null default 'en' check (language in ('en','hi','te')),
  status text not null default 'active' check (status in ('invited','active','on_notice','inactive','left')),
  joined_on date,
  left_on date,
  staff_type text not null default 'teaching' check (staff_type in ('teaching','non_teaching','admin','support','driver','attendant')),
  is_teaching boolean generated always as (staff_type = 'teaching') stored,
  is_part_time boolean not null default false,
  max_periods_day integer,
  max_periods_week integer,
  unavailable jsonb not null default '[]',
  ui_prefs jsonb not null default '{}',
  custom jsonb not null default '{}',
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, user_id) references core.org_users(org_id, user_id) on delete set null (user_id),
  foreign key (org_id, photo_file_id) references core.files(org_id, id),
  foreign key (org_id, position_id) references core.positions(org_id, id),
  foreign key (org_id, department_id) references core.departments(org_id, id),
  foreign key (org_id, wing_id) references core.wings(org_id, id),
  foreign key (org_id, reports_to) references core.staff(org_id, id)
);
create index staff_branch on core.staff(org_id, branch_id);
create index staff_user_id on core.staff(org_id, user_id);
create index staff_photo_file_id on core.staff(org_id, photo_file_id);
create index staff_position_id on core.staff(org_id, position_id);
create index staff_department_id on core.staff(org_id, department_id);
create index staff_wing_id on core.staff(org_id, wing_id);
create index staff_reports_to on core.staff(org_id, reports_to);
create unique index staff_employee_code on core.staff(org_id, employee_code) where employee_code is not null and deleted_at is null;
create index staff_name on core.staff(org_id, full_name);
create trigger trg_touch before update on core.staff for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.staff to authenticated, crm_server, os_server, erp_server;
grant select on core.staff to platform_admin_server;
select app.apply_core_rls('staff', 'staff', '*', 'staff', null, null);

-- Neutral "section / batch / division" teaching group of a programme for a year.
create table core.sections (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  programme_id uuid not null,
  academic_year_id uuid,
  name text not null,
  class_teacher_id uuid,
  room_id uuid,
  capacity integer check (capacity is null or capacity >= 0),
  strength integer not null default 0,
  profile jsonb not null default '{}',
  seq integer not null default 0,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, programme_id) references core.programmes(org_id, id) on delete cascade,
  foreign key (org_id, academic_year_id) references core.academic_years(org_id, id),
  foreign key (org_id, class_teacher_id) references core.staff(org_id, id),
  foreign key (org_id, room_id) references core.rooms(org_id, id),
  unique nulls not distinct (org_id, programme_id, academic_year_id, name)
);
create index sections_programme_id on core.sections(org_id, programme_id);
create index sections_academic_year_id on core.sections(org_id, academic_year_id);
create index sections_class_teacher_id on core.sections(org_id, class_teacher_id);
create index sections_room_id on core.sections(org_id, room_id);
create trigger trg_touch before update on core.sections for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.sections to authenticated, crm_server, os_server, erp_server;
